<template><section class="tax-page"><div v-if="loadError" class="bio-nexus-message bio-nexus-message-error"><strong>No fue posible cargar los impuestos.</strong><span>{{loadError}}</span></div><section class="bio-nexus-administrative-directory"><div v-if="loading" class="bio-nexus-empty-state">Cargando impuestos...</div><BioNexusDataGrid v-else class="tax-grid" :row-data="rows" :column-defs="columns" :default-col-def="defaults" :components="components" :get-row-id="getRowId" :search-enabled="true" v-model:search-model-value="search" search-placeholder="Buscar impuesto" :refresh-enabled="true" :refreshing="loading" :refresh-disabled="saving" :page-size="10" :page-size-selector="[10,20,50,100]" :min-grid-height="300" :max-grid-height="560" empty-text="No existen impuestos para mostrar." @refresh="load"><template #actions><button v-if="canCreate" type="button" class="bio-nexus-action bio-nexus-action-primary" :disabled="saving" @click="formDialog?.openCreate()"><BioNexusActionIcon action="create"/><span>Nuevo impuesto</span></button></template></BioNexusDataGrid></section><TaxDialog ref="formDialog" :saving="saving" @submit="save"/><TaxDeleteDialog ref="deleteDialog" :saving="saving" @confirm="remove"/></section></template>
<script setup>import{computed,onMounted,ref}from"vue";import BioNexusDataGrid from"@/components/grid/BioNexusDataGrid.vue";import BioNexusGridActionsCell from"@/components/grid/BioNexusGridActionsCell.vue";import BioNexusGridToggleCell from"@/components/grid/BioNexusGridToggleCell.vue";import BioNexusOptionFilter from"@/components/grid/BioNexusOptionFilter.vue";import BioNexusActionIcon from"@/components/ui/BioNexusActionIcon.vue";import TaxDialog from"@/components/tax/TaxDialog.vue";import TaxDeleteDialog from"@/components/tax/TaxDeleteDialog.vue";import{useBioNexusToast}from"@/composables/useBioNexusToast";import{createTax,deleteTax,getTaxes,getTaxErrorMessage,updateTax}from"@/services/taxService";import{useAuthorizationStore}from"@/stores/authorization";const auth=useAuthorizationStore(),toast=useBioNexusToast(),rows=ref([]),loading=ref(false),saving=ref(false),loadError=ref(""),search=ref(""),formDialog=ref(null),deleteDialog=ref(null);const canCreate=computed(()=>auth.hasPermission("tax.create")),canUpdate=computed(()=>auth.hasPermission("tax.update")),canDelete=computed(()=>auth.hasPermission("tax.delete"));const defaults=Object.freeze({sortable:true,filter:true,resizable:true,suppressHeaderMenuButton:true}),components=Object.freeze({BioNexusGridActionsCell,BioNexusGridToggleCell}),yesNo=Object.freeze([{value:true,label:"Si"},{value:false,label:"No"}]);const columns=computed(()=>[{field:"description",headerName:"Descripcion",minWidth:220,flex:1},{field:"value",headerName:"Porcentaje",width:150,valueFormatter:({value})=>`${Number(value).toFixed(2)} %`},...["only_dollars","always_subtotal","hide"].map((field,index)=>({field,headerName:["Solo dolares","Fijo en subtotal","Oculto"][index],width:170,filter:BioNexusOptionFilter,filterParams:{options:yesNo},cellRenderer:BioNexusGridToggleCell,cellRendererParams:{onLabel:"Si",offLabel:"No",disabled:()=>true}})),{headerName:"Acciones",colId:"actions",width:110,pinned:"right",lockPinned:true,sortable:false,filter:false,resizable:false,cellClass:"bio-nexus-grid-actions-cell",cellRenderer:BioNexusGridActionsCell,cellRendererParams:{actions:[{key:"edit",label:"Editar",icon:"edit",visible:()=>canUpdate.value,disabled:()=>saving.value,onClick:row=>formDialog.value?.openEdit(row)},{key:"delete",label:"Eliminar",icon:"delete",visible:()=>canDelete.value,disabled:()=>saving.value,onClick:row=>deleteDialog.value?.open(row)}]}}]);function getRowId({data}){return String(data.id)}function replace(value){const next=rows.value.map(row=>row.id===value.id?value:row);if(!next.some(row=>row.id===value.id))next.push(value);rows.value=next.sort((a,b)=>a.description.localeCompare(b.description))}async function load(){if(loading.value||saving.value)return;loading.value=true;loadError.value="";try{rows.value=await getTaxes()}catch(error){rows.value=[];loadError.value=getTaxErrorMessage(error,"No fue posible consultar los impuestos.");toast.error(loadError.value)}finally{loading.value=false}}async function save(payload){if(saving.value)return;saving.value=true;formDialog.value?.clearError();try{const value=payload.mode==="create"?await createTax(payload.values):await updateTax(payload.record.id,payload.values);replace(value);formDialog.value?.close();toast.success(payload.mode==="create"?"Impuesto creado correctamente.":"Impuesto actualizado correctamente.")}catch(error){formDialog.value?.setError(getTaxErrorMessage(error,"No fue posible guardar el impuesto."))}finally{saving.value=false}}async function remove(record){if(saving.value||!record)return;saving.value=true;deleteDialog.value?.clearError();try{await deleteTax(record.id);rows.value=rows.value.filter(row=>row.id!==record.id);deleteDialog.value?.close();toast.success("Impuesto eliminado correctamente.")}catch(error){deleteDialog.value?.setError(getTaxErrorMessage(error,"No fue posible eliminar el impuesto."))}finally{saving.value=false}}onMounted(load)</script><style scoped>.tax-page,.tax-grid{min-width:0}.tax-grid :deep(.bio-nexus-grid-actions-cell){justify-content:center}.tax-grid :deep(.ag-pinned-right-header),.tax-grid :deep(.ag-pinned-right-cols-container){border-left:1px solid var(--bio-nexus-color-border-strong)}</style>